def sha(x): return hashlib.sha256(x.encode('utf-8')).hexdigest()
cells=[json.loads(s) for s in (OUT/'source-current-cells.jsonl').read_text().splitlines()]
for batch,locales in [('batch-03',['ja','ko','pt_BR']),('batch-04',['vi','zh_Hans','zh_Hant'])]:
 rows=[]; counts=collections.Counter()
 crossreview={}
 if batch=='batch-03' and (OUT/'batch-03-crossreview.jsonl').exists():
  crossreview={(x['sourcePosition'],x['locale']):x for x in
   (json.loads(s) for s in (OUT/'batch-03-crossreview.jsonl').read_text().splitlines())}
 for c in cells:
  if c['locale'] not in locales: continue
  cross=crossreview.get((c['sourcePosition'],c['locale']))
  if cross and cross['crossReviewDisposition']=='revise':
   assert cross['sourceId']==c['sourceId']
   assert cross['primaryFinalTargetHash']
   target=cross['recommendedTarget']; rationale='Primary adjudication adopted the independent cross-review recommendation: '+cross['rationale']
   refinement=PRIMARY_REFINEMENTS.get((c['locale'],c['sourcePosition']))
   if refinement:
    target,why=refinement
    rationale='Primary adjudication adopted the independent cross-review recommendation with a focused terminology refinement: '+why+' Cross-review rationale: '+cross['rationale']
   disp='propose-correction'; confidence=cross['confidence']
   reviewer='primary-static-semantic-review-adjudicated-crossreview'
   if target==c['currentTarget']: raise SystemExit(f'no-op cross-review correction {c["locale"]}:{c["sourcePosition"]}')
   final=target; counts[disp]+=1
   rows.append({'sourcePosition':c['sourcePosition'],'sourceId':c['sourceId'],'locale':c['locale'],'currentTargetHash':c['currentTargetHash'],'disposition':disp,'finalTarget':final,'rationale':rationale,'confidence':confidence,'reviewer':reviewer})
   continue
  fix=FIX.get(c['locale'],{}).get(c['sourcePosition'])
  if fix:
   target,rationale=fix; disp='propose-correction'; confidence='moderate'
   if target==c['currentTarget']: raise SystemExit(f'no-op correction {c["locale"]}:{c["sourcePosition"]}')
   final=target; counts[disp]+=1
  else:
   disp='accept-current'; final=c['currentTarget']; confidence='moderate'
   rationale='Current wording preserves the English meaning in the pinned reader-service context; its placeholders, markup, protected literals, and app labels were reviewed.'
   counts[disp]+=1
  rows.append({'sourcePosition':c['sourcePosition'],'sourceId':c['sourceId'],'locale':c['locale'],'currentTargetHash':c['currentTargetHash'],'disposition':disp,'finalTarget':final,'rationale':rationale,'confidence':confidence,'reviewer':'primary-static-semantic-review'})
 assert len(rows)==300 and len({(x['sourcePosition'],x['locale']) for x in rows})==300
 assert {x['locale'] for x in rows}==set(locales)
 (OUT/f'{batch}-review.jsonl').write_text(''.join(json.dumps(x,ensure_ascii=False,sort_keys=True)+'\n' for x in rows))
 print(json.dumps({'batch':batch,'rows':len(rows),'counts':dict(counts),'corrected':len(FIX.get(locales[0],{}))},ensure_ascii=False))
